-- State transitions declared for Party: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION party.parties_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'blocked'), ('active', 'inactive'), ('blocked', 'active'), ('inactive', 'active'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: parties.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_parties__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS parties_status_transition_check ON party.parties;
CREATE TRIGGER parties_status_transition_check
    BEFORE UPDATE OF "status" ON party.parties
    FOR EACH ROW EXECUTE FUNCTION party.parties_status_transition_check();
